          </Col>
          <Col xs={24} sm={12} lg={8}>
            <Card style={{ borderRadius: 14 }}>
              <Statistic title="订单总数" value={stats?.totalOrders ?? 0} />
            </Card>
          </Col>
          <Col xs={24} sm={12} lg={8}>
            <Card style={{ borderRadius: 14 }}>
